export function getAllPosts(): BlogPost[] {
  return blogPosts;
}

export function getPostBySlug(slug: string): BlogPost | undefined {
  return blogPosts.find((p) => p.slug === slug);
}

export function getAllCategories(): string[] {
  return Array.from(BLOG_CATEGORIES);
}

export function getPostsByCategory(category: string): BlogPost[] {
  if (!category || category === "All") return blogPosts;
  return blogPosts.filter((p) => p.category.toLowerCase() === category.toLowerCase());
}

export function getFeaturedPost(): BlogPost {
  return blogPosts[0]; // Latest article
}

export function getRelatedPosts(currentSlug: string, count = 3): BlogPost[] {
  const current = getPostBySlug(currentSlug);
  if (!current) return blogPosts.slice(0, count);

  const related = current.relatedSlugs
    .map((slug) => getPostBySlug(slug))
    .filter((p): p is BlogPost => Boolean(p));

  if (related.length < count) {
    const additional = blogPosts
      .filter((p) => p.slug !== currentSlug && !related.some((r) => r.slug === p.slug))
      .slice(0, count - related.length);
    return [...related, ...additional];
  }

  return related.slice(0, count);
}

export function getPaginatedPosts(
  page = 1,
  limit = 9,
  category = "All"
): PaginatedBlogResult {
  const filtered = getPostsByCategory(category);
  const totalPosts = filtered.length;
  const totalPages = Math.max(1, Math.ceil(totalPosts / limit));
  const currentPage = Math.min(Math.max(1, page), totalPages);

  const startIndex = (currentPage - 1) * limit;
  const posts = filtered.slice(startIndex, startIndex + limit);

  return {
    posts,
    totalPages,
    totalPosts,
    currentPage,
  };
}
